import { payments } from '../../lib/parcel-client.js';

function freezeTree(value) {
  if (value && typeof value === 'object') {
    Object.values(value).forEach(freezeTree);
    Object.freeze(value);
  }
  return value;
}

export async function confirmDonation(donation) {
  const snapshot = freezeTree(structuredClone({
    amountCents: donation.cents,
    dedication: donation.dedication,
  }));
  const options = { idempotencyKey: 'donation:' + donation.reference };
  try {
    return await payments.submit(snapshot, options);
