import { reservations } from '../../lib/parcel-client.js';

export async function holdEventPackages(eventId, packages) {
  const work = packages.map(pack => ({
    orderId: eventId, sku: pack.stockCode, quantity: pack.count,
  }));
  const issues = work
    .filter(item => !item.sku || !Number.isInteger(item.quantity) || item.quantity <= 0)
    .map(() => 'Invalid package');
  const holds = [];
  if (issues.length === 0) {
    for (const item of work) holds.push(await reservations.reserve(item));
  }
  return { issues, holds };
}

````

